 ss::Authority recoveryAuthority;std::function<void()> prepareHook;
 Backend(){active.scope={ymcc::windows_motion::retain(sink,100),1};active.model=model();active.pair=pair("A");active.api={"winrt","winrt"};active.profile=ss::fingerprint(active.model);active.calibrationKey="KNOWN-DEFAULT-A-KEY";active.lifetime=active.currentLifetime=1;active.currentPower=1;active.resource=1;active.acceptsChanges=true;refreshFrame(0);}
 void refreshFrame(std::uint64_t selection){ss::LiveFrame f;f.captureLease=active.captureLease;f.captureScope=inv::Ticket{ymcc::windows_motion::retain(captureSink,100),1};f.authority=active.authority;f.captureAuthority=active.captureAuthority;f.scope=active.scope;f.lifetime=active.lifetime;f.selectionId=selection;f.pair=active.pair;f.profile=active.profile;f.calibrationKey=active.calibrationKey;for(unsigned kind=0;kind<2;++kind){auto& v=f.values[kind];v.captureLease=active.captureLease;v.captureScope=f.captureScope;v.scope=active.scope;v.lifetime=active.lifetime;v.authority=active.authority;v.captureAuthority=active.captureAuthority;v.kind=kind==0?inv::Kind::Gyro:inv::Kind::Accel;v.id=kind==0?active.pair.gyroId:active.pair.accelId;v.provider=provider(v.id);v.api=active.api[kind];v.standardUnits=v.usable=true;v.readingTransform=0;v.sample={double(kind+1),2,3,clock*100,clock};}active.frame=std::move(f);}
 void close(std::uint64_t token){if(!token||closed.count(token)||!resources.count(token)){duplicateClose=true;return;}if(captureCells.count(token)){captureCells.at(token)->store(false);captureCells.erase(token);}closed.insert(token);resources.erase(token);}
 static std::uint64_t now(void* p)noexcept{return static_cast<Backend*>(p)->clock;}
