 for(const std::string cause:{"power","lifetime","cancel","other-writer"}){Backend b;b.behavior=cause;ss::SelectionTransaction txn;const auto r=txn.apply(request(1,pair("B")),b.ops());check(r.outcome==ss::Outcome::Retired&&b.recovers==0&&b.quarantines==0,"never restore over changed lifecycle or another writer: "+cause);b.cleanup();}
 {Backend b;b.throwBeforeAdopt=true;ss::SelectionTransaction txn;auto r=txn.apply(request(1,pair("B")),b.ops());check(r.outcome==ss::Outcome::Rejected&&b.releases==1&&b.adopts==0,"snapshot failure before adoption releases candidate only");b.cleanup();}
 {Backend b;b.throwAfterAdopt=true;ss::SelectionTransaction txn;auto r=txn.apply(request(1,pair("B")),b.ops());check(r.outcome==ss::Outcome::RecoveryRequired&&b.quarantines==1&&b.sink->activeBindingGeneration==0&&b.releases==0,"unknown post-adopt snapshot quarantines owned input without closing active handle");b.cleanup();}
 {Backend b;ss::SelectionTransaction txn;ss::Receipt nested;b.prepareHook=[&]{nested=txn.apply(request(2,pair("C")),b.ops());};const auto r=txn.apply(request(1,pair("B")),b.ops());check(r.outcome==ss::Outcome::Committed&&nested.outcome==ss::Outcome::Busy&&b.prepares==1,"reentrant writer refused without lock deadlock");b.cleanup();}
